    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            cells = []
            while stack:
                y,x = stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy,x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 3 and q not in seen:
                        seen.add(q); stack.append(q)
            ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
            if len(cells) >= 8:
                boxes.append((min(ys), max(ys), min(xs), max(xs)))
